head.script:
scwin.onpageload = function() {
scwin.windowId = 0;
};
scwin.onpageunload = function() {};
scwin.createWindowAuto = function() {
    var c_subName = "windowContainer_spaAuto_WPFF-148_(WSQ-3499)_sub";
    var c_xmlName = ".xml";
    var frameMode = "";
    for (var i = 0; i < 3; i++) {
        if (i % 2) {
            frameMode = "iframe";
        } else {
            frameMode = "wframe";
        }
        windowContainer1.createWindow(c_subName + i + frameMode, null,
            c_subName + i + c_xmlName, "", null, "existWindow", null,
            null, null, null, frameMode);
    }
}
scwin.createWindow = function() {
    var c_subName = "windowContainer_spaAuto_WPFF-148_(WSQ-3499)_sub";
    var c_xmlName = ".xml";
    var frameMode = "";
    if (scwin.windowId % 2) {
        frameMode = "iframe";
    } else {
        frameMode = "wframe";
    }
    windowContainer1.createWindow(c_subName + scwin.windowId + frameMode, null,
        c_subName + scwin.windowId + c_xmlName, "", null, "existWindow", null,
        null, null, null, frameMode);
    scwin.windowId++;
}
scwin.btn_createWindow_onclick = function(e) {
    scwin.createWindow();
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_createWindow').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('windowContainer1_subWindow0_wframe') != null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
